<?php
if (!defined('ABSPATH')) exit;
global $product;
if (!$product || !$product->is_visible()) return;
$pid=$product->get_id();$bhopts=get_option('bhc_options',[]);$specs=[];
foreach($product->get_attributes() as $attribute){$label=wc_attribute_label($attribute->get_name());$values=$attribute->is_taxonomy()?wc_get_product_terms($pid,$attribute->get_name(),['fields'=>'names']):$attribute->get_options();if($values)$specs[$label]=implode('، ',$values);if(count($specs)>=4)break;}
$payload=['id'=>$pid,'title'=>$product->get_name(),'url'=>get_permalink($pid),'price'=>wp_strip_all_tags($product->get_price_html()),'image'=>get_the_post_thumbnail_url($pid,'woocommerce_thumbnail')?:wc_placeholder_img_src(),'sku'=>$product->get_sku(),'specs'=>$specs];
?><li <?php wc_product_class('bhp-product-card',$product); ?>><div class="bhp-card-media"><a class="bhp-card-photo" href="<?php the_permalink(); ?>"><?php echo wp_kses_post($product->get_image('bh-product-card',['loading'=>'lazy','sizes'=>'(max-width: 600px) 45vw, (max-width: 1000px) 32vw, 260px'])); ?></a><?php if($product->is_on_sale()):?><span class="bhp-sale-tag">پیشنهاد ویژه</span><?php endif;?><?php if(!$product->is_in_stock()):?><span class="bhp-stock-tag">ناموجود</span><?php endif;?><div class="bhp-quick-actions"><?php if(!empty($bhopts['show_wishlist'])):?><button type="button" class="bhp-icon-btn bhp-wish" data-item="<?php echo esc_attr(wp_json_encode($payload));?>" aria-label="افزودن به علاقه‌مندی‌ها" aria-pressed="false">♡</button><?php endif;?><?php if(!empty($bhopts['show_compare'])):?><button type="button" class="bhp-icon-btn bhp-compare" data-item="<?php echo esc_attr(wp_json_encode($payload));?>" aria-label="افزودن به مقایسه" aria-pressed="false">⇄</button><?php endif;?></div></div><div class="bhp-card-content"><div class="bhp-card-cat"><?php echo wp_kses_post(wc_get_product_category_list($pid)); ?></div><h2 class="woocommerce-loop-product__title"><a href="<?php the_permalink(); ?>"><?php echo esc_html($product->get_name()); ?></a></h2><?php if(!empty($bhopts['show_rating'])&&$product->get_average_rating()):?><div class="bhp-rating">★ <span><?php echo esc_html(wc_format_decimal($product->get_average_rating(),1));?></span> <small>(<?php echo intval($product->get_review_count());?> دیدگاه)</small></div><?php endif;?><div class="bhp-card-foot"><span class="price"><?php echo wp_kses_post($product->get_price_html()); ?></span><?php if($product->is_purchasable()&&$product->is_in_stock()):if($product->is_type('simple')):?><a href="<?php echo esc_url($product->add_to_cart_url());?>" data-quantity="1" data-product_id="<?php echo esc_attr($pid);?>" class="button bhp-add-to-cart add_to_cart_button ajax_add_to_cart" rel="nofollow" aria-label="افزودن به سبد خرید">+</a><?php else:?><a class="button bhp-add-to-cart" href="<?php echo esc_url(get_permalink($pid));?>" aria-label="انتخاب ویژگی‌ها">←</a><?php endif;else:?><a class="button bhp-add-to-cart" href="<?php echo esc_url(get_permalink($pid));?>" aria-label="مشاهده محصول">↗</a><?php endif;?></div></div></li>
